      note: `<p>Это парадокс Симпсона: направление зависимости в целом противоположно направлению в каждой группе. На продуктовых секциях его спрашивают постоянно, и не из любви к теории — так выглядит примерно каждое третье «падение метрики» в жизни.</p>
<p>Защита простая и механическая: <strong>любое изменение доли смотрите вместе с изменением структуры</strong>. Если веса сегментов сдвинулись, сравнивать общие числа нельзя, пока вы не зафиксировали структуру — например, пересчитав «а какой была бы конверсия при прошлом миксе». Здесь: 0,8 × 2,60% + 0,2 × 1,10% = 2,30%, то есть при старой структуре конверсия выросла бы с 2,20% до 2,30%.</p>`
