  starter: `-- Воронка: пять шагов, потери и две конверсии
-- Шаг 1: задайте справочник шагов через VALUES
-- Шаг 2: посчитайте уникальных пользователей на каждом шаге
-- Шаг 3: добавьте LAG и FIRST_VALUE для конверсий

WITH steps(step_no, step_name) AS (
    VALUES (1,'visit')
    -- остальные шаги
),
reached AS (
    SELECT
        s.step_no,
        s.step_name
        -- количество пользователей
    FROM steps s
    LEFT JOIN events e ON
    GROUP BY
)
SELECT
    step_no,
    step_name,
    users
    -- lost, from_prev, from_top
FROM reached
ORDER BY step_no;
`,

