      note: `<p>Главное, что стоит унести: <strong>липучесть сравнивают с историей того же продукта и с прямыми конкурентами, а не между категориями</strong>. Требование «поднять DAU/MAU до уровня соцсети» к приложению для покупки билетов — типичная управленческая ошибка, которая приводит к навязчивым уведомлениям и падению удержания.</p>
<p>И общее правило работы с отношениями, которое встречалось уже трижды за курс: у дроби всегда смотрят числитель и знаменатель по отдельности. Липучесть растёт и когда DAU увеличивается, и когда MAU падает, а это противоположные новости.</p>`
