      note: `<p>Возражение «дайте больше времени» звучит на каждом обсуждении unit-экономики, и почти всегда его можно проверить за десять минут. Ключевой приём — посмотреть, <strong>какая доля выручки уже собрана</strong>, а не спорить о том, сколько ещё может прийти.</p>
<p>Здесь проверка не просто отвергла возражение — она перевернула его. Быстро выдыхаются именно платные каналы, а долгий хвост есть у органики. Ответ маркетингу получается сильным: «расширение горизонта не спасёт платный трафик, оно увеличит разрыв».</p>
<p>Обратите внимание и на то, чего в этом ответе нет: рекомендации отключить каналы. Аналитик показал, что деньги на этом горизонте не возвращаются и что «подождать» не поможет. Решение о бюджете принимает бизнес, у которого могут быть причины держать долю рынка. Разделять «что показывают данные» и «что делать» — часть профессии.</p>`
