  reference: `
<p><strong>Эталон — техническое задание на дашборд.</strong></p>
<p><em>Читатель и решения.</em> Продакт мобильного приложения, смотрит по понедельникам и перед планированием спринта. Решения, которые он принимает по этому экрану: что взять в работу на неделю (какой шаг воронки чинить), нужно ли поднимать тревогу по удержанию, стоит ли идти к маркетингу с разговором про качество трафика. Финансовые итоги и отчётность для руководства сюда не входят — это отдельный дашборд с другим читателем.</p>
<p><em>Верхний блок: пять чисел, каждое с изменением к прошлой неделе и полосой обычного разброса за 8 недель.</em></p>
<ul>
  <li>Установки за неделю</li>
  <li>WAU</li>
  <li>Сквозная конверсия в покупку с окном 7 дней</li>
  <li>Удержание первой недели последней завершённой когорты</li>
  <li>Выручка за неделю</li>
</ul>
<p>Почему именно эти: первые два отвечают за приток и активность, третье и четвёртое — за качество продукта, пятое связывает всё с деньгами. Пятое число здесь не для отчётности, а как предохранитель: если продуктовые метрики растут, а выручка нет, что-то посчитано не так.</p>
<p><em>Средний блок: четыре виджета.</em></p>
<ol>
  <li><strong>Воронка по пяти шагам</strong> с окном 7 дней: число людей, конверсия шага и абсолютные потери. Фильтр по платформе и каналу. Отвечает на вопрос «что чинить».</li>
  <li><strong>Когортная таблица удержания</strong> по неделям, последние 8 когорт, ячейки с неполным наблюдением пустые. Отвечает на вопрос «стало лучше или хуже».</li>
  <li><strong>График установок по каналам</strong> с накоплением по неделям — чтобы сдвиг структуры трафика был виден сразу, а не обнаруживался расследованием, как в уроке 4.3.</li>
  <li><strong>Таблица каналов:</strong> установки, конверсия в покупку, удержание четвёртой недели, LTV90, CAC, ROI. Строки с ROI меньше единицы подсвечены.</li>
</ol>
<p><em>Нижний блок (отдельная вкладка):</em> RFM-сегменты с размерами и выручкой, распределение времени до первой покупки, список версий приложения с их конверсией. Это смотрят раз в месяц, на главном экране им не место.</p>
<p><em>Чего не будет и почему.</em></p>
<ul>
  <li><strong>DAU/MAU.</strong> Для еженедельных решений продакта липучесть бесполезна: она меняется медленно и не подсказывает действий. Место ей на дашборде руководства.</li>
  <li><strong>Круговая диаграмма долей каналов.</strong> Шесть долей углами не сравниваются. Вместо неё — область с накоплением по времени, где видна и структура, и её изменение.</li>
  <li><strong>Разрезы по городам.</strong> Семь городов дробят выборку до сегментов, в которых недельные колебания — чистый шум. Вернуть можно, если появится продуктовая гипотеза, требующая гео.</li>
  <li><strong>Накопленная выручка с начала года.</strong> Такой график растёт всегда и потому не несёт информации.</li>
</ul>
<p><em>Обновление.</em> Пересчёт каждую ночь, витрины считаются заранее, чтобы экран открывался за пару секунд. В заголовке — строка «данные по такое-то число включительно». Если ночной расчёт не прошёл, строка становится красной и показывает дату последних удачных данных: экран не должен молча показывать вчерашнее как сегодняшнее. Незавершённая текущая неделя показывается пунктиром или не показывается вовсе, иначе каждый понедельник будет выглядеть как обвал.</p>
<p><em>Определения.</em> К каждой метрике всплывающая подсказка: что в числителе, что в знаменателе, какое окно. Отдельно зафиксировано, что конверсия считается по уникальным пользователям с окном 7 дней от первого визита — иначе через квартал начнётся спор, чей расчёт правильный.</p>
<p><em>Как поймём, что он полезен.</em> Через месяц смотрю статистику открытий: сколько раз заходили и на какие виджеты кликали. Виджеты без кликов удаляю. Плюс простой признак: если продакт перестал приходить с вопросами, на которые дашборд отвечает, значит, работает. Если приходит с теми же вопросами — значит, ответ на экране есть, но найти его нельзя, и проблема в компоновке, а не в данных.</p>
<p><strong>Что отличает сильный ответ:</strong> в нём есть отказы. Список «что я покажу» умеет составить каждый; профессионализм виден в том, что человек сознательно убрал с экрана и может объяснить почему.</p>
`,

