      note: `<p>Обратите внимание на форму второго ответа. Аналитик не защищает своё число, а называет <strong>порог, при котором вывод изменится</strong>: «если CAC ниже 754, я неправ». Это переводит спор из позиционного в проверяемый и заодно показывает, что вы не держитесь за результат.</p>
<p>Третий ответ переформулирует возражение вместо того, чтобы его опровергать. Оппонент прав: объём упадёт. Спорить с этим бессмысленно, а вот перевести разговор с «делать или не делать» на «сколько это стоит» — ровно та работа, которую от аналитика ждут.</p>`
