window.FIGS["simpson-mix"] = "<svg class=\"fig-svg\" viewBox=\"-4 0 340 300\" role=\"img\" aria-labelledby=\"fig-simpson-mix-t fig-simpson-mix-d\"><title id=\"fig-simpson-mix-t\">Парадокс Симпсона: конверсия выросла в каждом канале и упала в целом</title><desc id=\"fig-simpson-mix-d\">Два канала, было и стало, по 10 000 визитов. Поиск: 4,0 → 4,2 процента. Реклама: 1,2 → 1,3. В целом: 3,30 → 2,17. Причина — доля рекламы выросла с 25 до 70 процентов.</desc><text class=\"f-hd\" x=\"0\" y=\"14\" font-size=\"12.5\">конверсия в покупку</text><line class=\"f-row\" x1=\"96\" y1=\"36\" x2=\"96\" y2=\"204\"/><text class=\"f-sub\" x=\"96\" y=\"220\" font-size=\"10.5\" text-anchor=\"middle\">было</text><line class=\"f-row\" x1=\"236\" y1=\"36\" x2=\"236\" y2=\"204\"/><text class=\"f-sub\" x=\"236\" y=\"220\" font-size=\"10.5\" text-anchor=\"middle\">стало</text><line class=\"f-row\" x1=\"86\" y1=\"204\" x2=\"246\" y2=\"204\"/><path class=\"f-raw\" d=\"M96 76.0 L236 69.6\"/><circle class=\"f-sub\" cx=\"96\" cy=\"76\" r=\"2.2\"/><circle class=\"f-sub\" cx=\"236\" cy=\"69.6\" r=\"2.2\"/><text class=\"f-sub\" x=\"88\" y=\"80\" font-size=\"10.5\" text-anchor=\"end\">4,0%</text><text class=\"f-sub\" x=\"244\" y=\"73.6\" font-size=\"10.5\">4,2%</text><text class=\"f-sub\" x=\"0\" y=\"80\" font-size=\"10.5\">поиск</text><path class=\"f-raw\" d=\"M96 165.6 L236 162.4\"/><circle class=\"f-sub\" cx=\"96\" cy=\"165.6\" r=\"2.2\"/><circle class=\"f-sub\" cx=\"236\" cy=\"162.4\" r=\"2.2\"/><text class=\"f-sub\" x=\"88\" y=\"169.6\" font-size=\"10.5\" text-anchor=\"end\">1,2%</text><text class=\"f-sub\" x=\"244\" y=\"166.4\" font-size=\"10.5\">1,3%</text><text class=\"f-sub\" x=\"0\" y=\"169.6\" font-size=\"10.5\">реклама</text><path class=\"f-pen\" d=\"M96 98.4 L236 134.6\"/><circle class=\"f-pen-fill\" cx=\"96\" cy=\"98.4\" r=\"2.6\"/><circle class=\"f-pen-fill\" cx=\"236\" cy=\"134.56\" r=\"2.6\"/><text class=\"f-pen-t\" x=\"88\" y=\"102.4\" font-size=\"11.5\" text-anchor=\"end\">3,30%</text><text class=\"f-pen-t\" x=\"244\" y=\"138.56\" font-size=\"11.5\">2,17%</text><text class=\"f-hd\" x=\"0\" y=\"102.4\" font-size=\"11.5\">итого</text><text class=\"f-pen-t\" x=\"330\" y=\"244\" font-size=\"11.5\" text-anchor=\"end\">доля рекламы: 25% → 70%</text><text class=\"f-note\" x=\"0\" y=\"268\" font-size=\"15\">каждый канал вырос —</text><text class=\"f-note\" x=\"0\" y=\"286\" font-size=\"15\">а сумма упала: сдвинулся микс</text></svg>";
window.FIGS["funnel-steps"] = "<svg class=\"fig-svg\" viewBox=\"-4 0 340 318\" role=\"img\" aria-labelledby=\"fig-funnel-steps-t fig-funnel-steps-d\"><title id=\"fig-funnel-steps-t\">Воронка «Дельта Маркет» по шагам</title><desc id=\"fig-funnel-steps-d\">Пять шагов, ширина полосы — число людей: визит 220, карточка 206, корзина 175, оформление 121, оплата 64. Конверсии шагов: 93,6, 85,0, 69,1, 52,9 процента. Хуже всего переход в оплату: там теряем 57 человек. Сквозная конверсия 29,1 процента.</desc><text class=\"f-hd\" x=\"0\" y=\"14\" font-size=\"12.5\">уникальные пользователи, без окна</text><rect class=\"f-box\" x=\"15\" y=\"30\" width=\"300\" height=\"24\" rx=\"4\"/><text class=\"f-hd\" x=\"165\" y=\"46\" font-size=\"11.5\" text-anchor=\"middle\">визит · 220</text><text class=\"f-sub\" x=\"165\" y=\"71\" font-size=\"10.5\" text-anchor=\"middle\">↓ 93,6%</text><rect class=\"f-box\" x=\"24.5455\" y=\"80\" width=\"280.909\" height=\"24\" rx=\"4\"/><text class=\"f-hd\" x=\"165\" y=\"96\" font-size=\"11.5\" text-anchor=\"middle\">карточка · 206</text><text class=\"f-sub\" x=\"165\" y=\"121\" font-size=\"10.5\" text-anchor=\"middle\">↓ 85,0%</text><rect class=\"f-box\" x=\"45.6818\" y=\"130\" width=\"238.636\" height=\"24\" rx=\"4\"/><text class=\"f-hd\" x=\"165\" y=\"146\" font-size=\"11.5\" text-anchor=\"middle\">корзина · 175</text><text class=\"f-sub\" x=\"165\" y=\"171\" font-size=\"10.5\" text-anchor=\"middle\">↓ 69,1%</text><rect class=\"f-box\" x=\"82.5\" y=\"180\" width=\"165\" height=\"24\" rx=\"4\"/><text class=\"f-hd\" x=\"165\" y=\"196\" font-size=\"11.5\" text-anchor=\"middle\">оформление · 121</text><text class=\"f-pen-t\" x=\"165\" y=\"221\" font-size=\"11.5\" text-anchor=\"middle\">↓ 52,9%   −57 человек</text><rect class=\"f-box\" x=\"121.364\" y=\"230\" width=\"87.2727\" height=\"24\" rx=\"4\"/><text class=\"f-hd\" x=\"165\" y=\"246\" font-size=\"11.5\" text-anchor=\"middle\">оплата · 64</text><text class=\"f-sub\" x=\"330\" y=\"276\" font-size=\"10.5\" text-anchor=\"end\">сквозная 29,1%</text><text class=\"f-note\" x=\"0\" y=\"298\" font-size=\"15\">здесь теряем больше всего —</text><text class=\"f-note\" x=\"0\" y=\"316\" font-size=\"15\">и в процентах, и в людях</text></svg>";
window.FIGS["retention-defs"] = "<svg class=\"fig-svg\" viewBox=\"-4 0 340 300\" role=\"img\" aria-labelledby=\"fig-retention-defs-t fig-retention-defs-d\"><title id=\"fig-retention-defs-t\">Удержание по двум определениям на одних и тех же пользователях</title><desc id=\"fig-retention-defs-d\">Две кривые удержания с нулевого по тридцатый день. Скользящее (активен в день N или позже): D1 56,8, D7 41,1, D14 30,4, D30 15,9 процента. Классическое (активен ровно в день N): D1 40,1, D7 18,8, D14 12,2, D30 6,5. На тридцатом дне разница в два с половиной раза.</desc><text class=\"f-hd\" x=\"0\" y=\"14\" font-size=\"12.5\">удержание дня N, 4000 пользователей</text><line class=\"f-row\" x1=\"34\" y1=\"220\" x2=\"322\" y2=\"220\"/><text class=\"f-sub\" x=\"28\" y=\"224\" font-size=\"10.5\" text-anchor=\"end\">0%</text><line class=\"f-row\" x1=\"34\" y1=\"175\" x2=\"322\" y2=\"175\"/><text class=\"f-sub\" x=\"28\" y=\"179\" font-size=\"10.5\" text-anchor=\"end\">25%</text><line class=\"f-row\" x1=\"34\" y1=\"130\" x2=\"322\" y2=\"130\"/><text class=\"f-sub\" x=\"28\" y=\"134\" font-size=\"10.5\" text-anchor=\"end\">50%</text><line class=\"f-row\" x1=\"34\" y1=\"85\" x2=\"322\" y2=\"85\"/><text class=\"f-sub\" x=\"28\" y=\"89\" font-size=\"10.5\" text-anchor=\"end\">75%</text><line class=\"f-row\" x1=\"34\" y1=\"40\" x2=\"322\" y2=\"40\"/><text class=\"f-sub\" x=\"28\" y=\"44\" font-size=\"10.5\" text-anchor=\"end\">100%</text><path class=\"f-raw\" d=\"M34.0 40.0 L43.6 147.8 L53.2 156.5 L62.8 162.2 L72.4 170.2 L82.0 176.6 L91.6 181.1 L101.2 186.2 L110.8 188.7 L120.4 190.9 L130.0 193.1 L139.6 195.4 L149.2 197.2 L158.8 198.2 L168.4 198.0 L178.0 199.3 L187.6 200.4 L197.2 201.1 L206.8 202.1 L216.4 203.0 L226.0 204.5 L235.6 204.6 L245.2 204.5 L254.8 206.4 L264.4 206.2 L274.0 206.9 L283.6 207.0 L293.2 207.9 L302.8 208.6 L312.4 209.7 L322.0 208.3\"/><path class=\"f-pen\" d=\"M34.0 40.0 L43.6 117.8 L53.2 123.5 L62.8 128.5 L72.4 133.8 L82.0 138.0 L91.6 141.6 L101.2 145.9 L110.8 148.9 L120.4 152.4 L130.0 155.4 L139.6 158.0 L149.2 161.0 L158.8 163.2 L168.4 165.3 L178.0 167.5 L187.6 170.2 L197.2 171.8 L206.8 173.8 L216.4 176.2 L226.0 178.2 L235.6 179.8 L245.2 181.5 L254.8 183.2 L264.4 184.6 L274.0 185.8 L283.6 187.2 L293.2 188.6 L302.8 189.5 L312.4 190.4 L322.0 191.4\"/><circle class=\"f-pen-fill\" cx=\"43.6\" cy=\"117.76\" r=\"2.6\"/><text class=\"f-pen-t\" x=\"46.6\" y=\"109.76\" font-size=\"11.5\" text-anchor=\"start\">56,8</text><circle class=\"f-sub\" cx=\"43.6\" cy=\"147.775\" r=\"2.2\"/><text class=\"f-sub\" x=\"49.6\" y=\"143.775\" font-size=\"10.5\" text-anchor=\"start\">40,1</text><circle class=\"f-pen-fill\" cx=\"101.2\" cy=\"145.93\" r=\"2.6\"/><text class=\"f-pen-t\" x=\"101.2\" y=\"137.93\" font-size=\"11.5\" text-anchor=\"middle\">41,1</text><circle class=\"f-sub\" cx=\"101.2\" cy=\"186.205\" r=\"2.2\"/><text class=\"f-sub\" x=\"101.2\" y=\"201.205\" font-size=\"10.5\" text-anchor=\"middle\">18,8</text><circle class=\"f-pen-fill\" cx=\"168.4\" cy=\"165.28\" r=\"2.6\"/><text class=\"f-pen-t\" x=\"168.4\" y=\"157.28\" font-size=\"11.5\" text-anchor=\"middle\">30,4</text><circle class=\"f-sub\" cx=\"168.4\" cy=\"197.995\" r=\"2.2\"/><text class=\"f-sub\" x=\"168.4\" y=\"212.995\" font-size=\"10.5\" text-anchor=\"middle\">12,2</text><circle class=\"f-pen-fill\" cx=\"322\" cy=\"191.425\" r=\"2.6\"/><text class=\"f-pen-t\" x=\"322\" y=\"183.425\" font-size=\"11.5\" text-anchor=\"end\">15,9</text><circle class=\"f-sub\" cx=\"322\" cy=\"208.3\" r=\"2.2\"/><text class=\"f-sub\" x=\"322\" y=\"223.3\" font-size=\"10.5\" text-anchor=\"end\">6,5</text><line class=\"f-row\" x1=\"43.6\" y1=\"220\" x2=\"43.6\" y2=\"224\"/><text class=\"f-sub\" x=\"43.6\" y=\"236\" font-size=\"10.5\" text-anchor=\"middle\">D1</text><line class=\"f-row\" x1=\"101.2\" y1=\"220\" x2=\"101.2\" y2=\"224\"/><text class=\"f-sub\" x=\"101.2\" y=\"236\" font-size=\"10.5\" text-anchor=\"middle\">D7</text><line class=\"f-row\" x1=\"168.4\" y1=\"220\" x2=\"168.4\" y2=\"224\"/><text class=\"f-sub\" x=\"168.4\" y=\"236\" font-size=\"10.5\" text-anchor=\"middle\">D14</text><line class=\"f-row\" x1=\"322\" y1=\"220\" x2=\"322\" y2=\"224\"/><text class=\"f-sub\" x=\"322\" y=\"236\" font-size=\"10.5\" text-anchor=\"middle\">D30</text><text class=\"f-pen-t\" x=\"235.6\" y=\"157.815\" font-size=\"11.5\" text-anchor=\"middle\">скользящее</text><text class=\"f-sub\" x=\"235.6\" y=\"230.565\" font-size=\"10.5\" text-anchor=\"middle\">классическое</text><text class=\"f-note\" x=\"0\" y=\"264\" font-size=\"15\">одни и те же люди — а числа</text><text class=\"f-note\" x=\"0\" y=\"282\" font-size=\"15\">расходятся в два с половиной раза</text></svg>";
